133	  add('shSwing', -SH.fixedStart, SH.fixedStart, SHZ - shH, SHZ + shH, stSongHanY, ST_GATE_SWING);
134	  add('songHanW', -SH_X, -SH.fixedStart, SHZ - shH, SHZ + shH, stSongHanY);
135	  add('songHanE', SH.fixedStart, SH_X, SHZ - shH, SHZ + shH, stSongHanY);
136	  /* Cầu Rồng: cả bề rộng giữa hai lan can */
137	  const drH = DR_RAIL_IN - R;                                       // 18,23
138	  add('dragon', -DR_X, DR_X, -drH, drH, stDragonY);
139	  /* Cầu Tình Yêu: kéo vào bờ qua khe lan can kè (promenade.ts bỏ lan can ở |z − love.z| < width/2 + railGap); lối vào duy nhất là cạnh x = BANK_IN chung với vùng bờ Đông */
140	  add('love', LV_X0 + R, BANK_IN, LV.z - (LV_IN - R), LV.z + (LV_IN - R), stLoveY);
141	  /* đầu cầu trên bờ: đường nối dài, cùng cao độ với vùng bờ */
142	  for (const [id, s] of [['dragonW', -1], ['dragonE', 1]] as [string, number][]) {
143	    add(id, s < 0 ? BX.x0 : DR_X, s < 0 ? -DR_X : BX.x1, -AX_SIDE.z1, AX_SIDE.z1, stBankY);
144	  }
145	  for (const [id, s] of [['shLandW', -1], ['shLandE', 1]] as [string, number][]) {
146	    add(id, s < 0 ? BX.x0 : SH_X, s < 0 ? -SH_X : BX.x1, SHZ - SH_LAND_HALF, SHZ + SH_LAND_HALF, stBankY);
147	  }
148	  /* hai bờ: từ lan can kè lùi radius (cả chỗ không có lan can ở chân cầu: vùng bờ đã cắt quanh cầu) ra tới hết khung; cắt quanh thân Cầu Rồng (|z| < 19,35) và thân Cầu sông Hàn (|dz| < 7,3) */
149	  const drCut = DR_EDGE + R, shCut = SH_ABUT + R;
150	  for (const [id, s] of [['bankW', -1], ['bankE', 1]] as [string, number][]) {
151	    const x0 = s < 0 ? BX.x0 : BANK_IN, x1 = s < 0 ? -BANK_IN : BX.x1;
152	    add(id, x0, x1, BX.z0, SHZ - shCut, stBankY);
153	    add(id, x0, x1, SHZ + shCut, -drCut, stBankY);
154	    add(id, x0, x1, drCut, BX.z1, stBankY);
155	  }
156	  return zs;
157	}
158	
159	/* ===== Đường tim thân rồng: chép điểm điều khiển body.ts:27-38 và CatmullRomCurve3 centripetal của three (không import three) ===== */
160	export function stSpinePoints(): [number, number][] {
161	  const pts: [number, number][] = [];
162	  const add = (x: number, yr: number) => pts.push([x, deckY(x) + yr]);
163	  add(-366, 11); add(-361, 16); add(-354, 17.5); add(-347, 14); add(-340, 8.5); add(-331, 4.5); add(-316, 3.0); add(-298, 3.4); add(-276, 2.4);
164	  let x0 = -CONFIG.mainTotal / 2; add(x0, -3);
165	  for (const s of CONFIG.mainSpans) {
166	    const rise = CONFIG.spanRise[s];
167	    for (const t of [0.12, 0.28, 0.5, 0.72, 0.88]) add(x0 + s * t, -3 + (rise + 3) * Math.sin(Math.PI * t));
168	    x0 += s; add(x0, -3);
169	  }
170	  add(272, 2.4); add(289, 3.0); add(303, 4.6); add(314, 7.4); add(323, 10.4); add(330, 13);
171	  return pts;
172	}
173	/* Một trục của đa thức Catmull-Rom không đều (giống CubicPoly.initNonuniformCatmullRom của three) */
174	function stCr(a: number, b: number, c: number, d: number, dt0: number, dt1: number, dt2: number, t: number): number {
175	  const t1 = ((b - a) / dt0 - (c - a) / (dt0 + dt1) + (c - b) / dt1) * dt1;
176	  const t2 = ((c - b) / dt1 - (d - b) / (dt1 + dt2) + (d - c) / dt2) * dt1;
177	  const c2 = -3 * b + 3 * c - 2 * t1 - t2, c3 = 2 * b - 2 * c + t1 + t2;
178	  return b + t1 * t + c2 * t * t + c3 * t * t * t;
179	}
180	export function stSpinePoint(pts: [number, number][], t: number, out: { x: number; y: number }): void {
181	  const l = pts.length, p = (l - 1) * t;
182	  let i = Math.floor(p), w = p - i;
183	  if (w === 0 && i === l - 1) { i = l - 2; w = 1; }
184	  const p1 = pts[i], p2 = pts[i + 1];
185	  const p0: [number, number] = i > 0 ? pts[i - 1] : [2 * pts[0][0] - pts[1][0], 2 * pts[0][1] - pts[1][1]];
186	  const p3: [number, number] = i + 2 < l ? pts[i + 2] : [2 * pts[l - 1][0] - pts[l - 2][0], 2 * pts[l - 1][1] - pts[l - 2][1]];
187	  const d = (a: [number, number], b: [number, number]) => Math.pow((a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2, 0.25);
188	  let dt0 = d(p0, p1), dt1 = d(p1, p2), dt2 = d(p2, p3);
189	  if (dt1 < 1e-4) dt1 = 1;
190	  if (dt0 < 1e-4) dt0 = dt1;
191	  if (dt2 < 1e-4) dt2 = dt1;
192	  out.x = stCr(p0[0], p1[0], p2[0], p3[0], dt0, dt1, dt2, w);
193	  out.y = stCr(p0[1], p1[1], p2[1], p3[1], dt0, dt1, dt2, w);
194	}
195	
196	/* Bán kính thân theo phần độ dài cung u (body.ts:15-20) */
197	function stSpineRadius(u: number): number {
198	  const Rb = CONFIG.bodyRadius, sm = (t: number) => t * t * (3 - 2 * t);
199	  if (u < 0.06) return 0.25 + (Rb - 0.25) * sm(u / 0.06);
200	  if (u > 0.95) return Rb + (CONFIG.headRadius - Rb) * sm((u - 0.95) / 0.05);
201	  return Rb;
202	}
203	
204	/* Thân / chân vòm / đầu / đuôi rồng trong tầm người: lấy mẫu đường tim, đánh dấu ô x (0,25 m) nơi ống thân (mặt cắt dọc z = 0)
205	   chạm dải [mặt cầu, mặt cầu + dải phân cách + REACH]; gộp ô liền nhau thành hình chữ nhật trên dải phân cách. */
206	function stDragonSolids(): StSolid[] {
207	  const pts = stSpinePoints(), N = 8000, p = { x: 0, y: 0 };
208	  const xs = new Float64Array(N + 1), ys = new Float64Array(N + 1), len = new Float64Array(N + 1);
209	  for (let i = 0; i <= N; i++) {
210	    stSpinePoint(pts, i / N, p); xs[i] = p.x; ys[i] = p.y;
211	    if (i > 0) len[i] = len[i - 1] + Math.hypot(xs[i] - xs[i - 1], ys[i] - ys[i - 1]);
212	  }
213	  const X0 = -400, STEP = 0.25, M = Math.round(800 / STEP) + 1;
214	  const half = new Float64Array(M);                                 // 0 = ô trống, > 0 = nửa bề ngang thân tại ô
215	  for (let i = 0; i <= N; i++) {
216	    const r = stSpineRadius(len[i] / len[N]), rr = 1.03 * r + 0.085;
217	    const g0 = Math.max(0, Math.ceil((xs[i] - rr - X0) / STEP)), g1 = Math.min(M - 1, Math.floor((xs[i] + rr - X0) / STEP));
218	    for (let g = g0; g <= g1; g++) {
219	      const x = X0 + g * STEP, lo = deckY(x), hi = lo + DR_MEDIAN + REACH;
220	      const yb = ys[i] < lo ? lo : ys[i] > hi ? hi : ys[i];
221	      const dx = xs[i] - x, dy = ys[i] - yb;
222	      if (dx * dx + dy * dy < rr * rr && rr > half[g]) half[g] = rr;
223	    }
224	  }
225	  const out: StSolid[] = [];
226	  let cur: StSolid = null, last = -Infinity;
227	  for (let g = 0; g < M; g++) {
228	    if (half[g] === 0) continue;
229	    const x = X0 + g * STEP;
230	    if (cur && x - last <= DR_ARCH_GAP) { cur.x1 = x + STEP; cur.z1 = Math.max(cur.z1, half[g]); cur.z0 = -cur.z1; }
231	    else { cur = { kind: 'rect', x0: x - STEP, x1: x + STEP, z0: -half[g], z1: half[g] }; out.push(cur); }
232	    last = x;
233	  }
234	  return out;
235	}
236	
237	/* Tháp chữ A, cột đôi, neo dây văng, hộp barie Cầu sông Hàn (tọa độ cục bộ + z cầu) */
238	function stSongHanSolids(): StSolid[] {
239	  const out: StSolid[] = [];
240	  const rect = (x0: number, x1: number, dz0: number, dz1: number, top?: number) => {
241	    const s: StSolid = { kind: 'rect', x0, x1, z0: SHZ + dz0, z1: SHZ + dz1 }; if (top !== undefined) s.top = top; out.push(s);
242	  };
243	  const H = SH_MEDIAN + REACH;                                      // tầm chặn tính từ mặt cầu, m
244	  rect(-0.4, 0.4, -1.0, 1.0);                                       // cột đôi ở tim (swingSpan.ts:45)
245	  const legIn = SH.aFoot - SH.aFoot * (H - 0.2) / (SH.aApex - 0.2); // ≈ 12,9 m — chân chữ A lên tới tầm H
246	  for (const s of [-1, 1]) {
247	    const a = legIn - 0.9, b = SH.aFoot + 0.9;                      // + nửa tiết diện 1,4 m chiếu ngang, làm tròn lên 0,9 (ước lượng)
248	    rect(s < 0 ? -b : a, s < 0 ? -a : b, -0.5, 0.5);                // chân chữ A, rộng 1,0 theo z
249	    for (let i = 0; i < SH.stays; i++) {                            // neo dây văng: dây thấp hơn tầm H trong đoạn gần neo
250	      const k = i / (SH.stays - 1), xd = SH.stayDeck[1] + (SH.stayDeck[0] - SH.stayDeck[1]) * k, top = SH.stayTop[1] + (SH.stayTop[0] - SH.stayTop[1]) * k;
251	      const xin = xd - (H - 0.35) * (xd - 0.5) / (top - 0.35);
252	      const a2 = xin - 0.1, b2 = xd + 0.3;                          // + bán kính dây, đầu neo (ước lượng)
253	      rect(s < 0 ? -b2 : a2, s < 0 ? -a2 : b2, -0.15, 0.15);        // dây 0,07 m + neo (ước lượng)
254	    }
255	    for (const sz of [-1, 1]) {                                     // hộp barie 0,45 × 1,0 trên gờ chắn bánh
256	      const bz = sz * (SH.hw - SH.sidewalk + 0.15);
257	      rect(s * SH.barrierX - 0.225, s * SH.barrierX + 0.225, bz - 0.225, bz + 0.225);
258	    }
259	    rect(-SH_X, SH_X, s < 0 ? -SH_CURB.z1 : SH_CURB.z0, s < 0 ? -SH_CURB.z0 : SH_CURB.z1, SH_CURB.top);   // gờ chắn bánh, liền qua khe nhịp quay
260	    for (const [x0, x1] of [[-SH_X, -SH.fixedStart], [SH.fixedStart, SH_X]]) {
261	      rect(x0, x1, s < 0 ? -SH_EDGE : SH_RAIL_IN, s < 0 ? -SH_RAIL_IN : SH_EDGE);   // lan can phần cố định (chặn hai đầu ở |x| = 290)
262	    }
263	  }
264	  return out;
265	}
266	
267	export function stBuildStructures(): StSolid[] {
268	  const out: StSolid[] = stDragonSolids();
269	  for (const s of [-1, 1]) {
270	    out.push({ kind: 'rect', x0: -DR_X, x1: DR_X, z0: s < 0 ? -DR_EDGE : DR_RAIL_IN, z1: s < 0 ? -DR_RAIL_IN : DR_EDGE });                 // lan can Cầu Rồng
271	    out.push({ kind: 'rect', x0: -DR_X, x1: DR_X, z0: s < 0 ? -DR_CURB.z1 : DR_CURB.z0, z1: s < 0 ? -DR_CURB.z0 : DR_CURB.z1, top: DR_CURB.top });   // gờ chắn xe
272	    out.push({ kind: 'rect', x0: LV_X0, x1: BK, z0: s < 0 ? LV.z - LV_RAIL : LV.z + LV_IN, z1: s < 0 ? LV.z - LV_IN : LV.z + LV_RAIL });      // lan can + khóa Cầu Tình Yêu
273	  }
274	  out.push(...stSongHanSolids());
275	  out.push({ kind: 'rect', x0: LV_X0 + 1.8 - 1.7, x1: LV_X0 + 1.8 + 1.7, z0: LV.z - 1.7, z1: LV.z + 1.7 });   // bệ + tượng cá chép hóa rồng (bệ cao 1,2 > lowMax)
276	  return out;
277	}
278	
279	export function stBuildStaticMap(): StMap {
280	  return stMakeMap(stBuildZones(), stBuildStructures(), CONFIG.stroll.radius);
281	}
282	
283	/* Điểm xuất phát slot: lệch theo x quanh spawn; slot < 0 (đi một mình) dùng giữa. Gọi một lần lúc vào chế độ, không mỗi khung */
284	export function stSpawn(map: StMap, slot: number, out: { x: number; z: number }): void {
285	  const S = CONFIG.stroll.spawn, k = slot < 0 ? 2 : slot;
286	  const x = S.x + S.spread * (k - 2), z = S.z;
287	  if (!stNearestValid(map, x, z, out)) { out.x = x; out.z = z; }
288	}
