  const map = makeMap(), s = at(map, 0, 5), g = s.y;
  let peak = 0, airFrames = 0, landed = -1;
  for (let i = 0; i < 120; i++) {
    stStep(s, inp({ jump: true }), map, 1 / 120);
    peak = Math.max(peak, s.y - g);
    if (s.air) { airFrames++; assert.equal(s.pose, 3); }
