  let d = (target - yaw) % (2 * Math.PI);
  if (d > Math.PI) d -= 2 * Math.PI; else if (d < -Math.PI) d += 2 * Math.PI;
  const k = turn * dt;
  return yaw + d * (k < 1 ? k : 1);
